/**
 * Render an icon.
 *
 * Each icon's paths are printed once in a hidden sprite at the end of the page
 * and referenced with <use>, so a page with 30 stars does not repeat 30 paths.
 * Icons are decorative by default (aria-hidden); pass a label to expose one.
 *
 * @param string $name  Icon name.
 * @param string $label Optional accessible label.
 * @param string $class Extra CSS classes.
 * @return string SVG markup or an empty string for unknown icons.
 */
function kms_icon( $name, $label = '', $class = '' ) {
	$icons = kms_icon_library();
	if ( ! isset( $icons[ $name ] ) ) {
		return '';
	}
	kms_icon_used( $name );
	$paint = 'fill' === $icons[ $name ][0]
		? 'fill="currentColor"'
		: 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';
	$a11y  = '' === $label
		? 'aria-hidden="true" focusable="false"'
		: 'role="img" aria-label="' . esc_attr( $label ) . '"';
	$class = trim( 'km-icon km-icon--' . $name . ' ' . $class );

	return '<svg class="' . esc_attr( $class ) . '" viewBox="0 0 24 24" width="24" height="24" ' . $paint . ' ' . $a11y . ' xmlns="http://www.w3.org/2000/svg"><use href="#kms-i-' . esc_attr( $name ) . '"></use></svg>';
}

/**
 * Remember which icons the page used.
 *
 * @param string|null $name Icon name to add; null to read the list.
 * @return string[]
 */
function kms_icon_used( $name = null ) {
	static $used = array();
	if ( null !== $name ) {
		$used[ $name ] = true;
	}
	return array_keys( $used );
}

/**
 * Print the sprite with every icon used on the page.
 */
function kms_icon_sprite() {
	$used = kms_icon_used();
	if ( ! $used ) {
		return;
	}
	$icons = kms_icon_library();
	echo '<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true" focusable="false">';
	foreach ( $used as $name ) {
		echo '<symbol id="kms-i-' . esc_attr( $name ) . '" viewBox="0 0 24 24">' . $icons[ $name ][1] . '</symbol>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- static SVG paths from this file.
	}
	echo '</svg>';
}
add_action( 'wp_footer', 'kms_icon_sprite', 1 );
